<script lang="ts">
 import{onMount,onDestroy}from'svelte';import{Api,ApiError}from'./lib/api';import type{DiscoveryStatus}from'./lib/discovery';import{lines,seenAt}from'./lib/discovery';
 export let api:Api;let status:DiscoveryStatus|null=null,enabled=false,publicUrl='',seeds='',seedLists='',blocked='',loading=true,busy=false,error='',success='';const abort=new AbortController();
 function init(value:DiscoveryStatus){status=value;enabled=value.config.enabled;publicUrl=value.config.public_url||api.origin;seeds=value.config.seeds.join('\n');seedLists=value.config.seed_lists.join('\n');blocked=value.config.blocked.join('\n');}
 function fail(cause:unknown){error=cause instanceof Error?cause.message:'Discovery settings failed.';if(cause instanceof ApiError&&cause.fields)error+=' '+Object.entries(cause.fields).map(([field,value])=>`${field.replaceAll('_',' ')}: ${value}`).join('; ');}
 async function load(){loading=true;error='';try{init(await api.request<DiscoveryStatus>('/host/discovery','GET',undefined,abort.signal));}catch(cause){if(!abort.signal.aborted)fail(cause);}finally{loading=false;}}
 async function save(event:SubmitEvent){event.preventDefault();busy=true;error='';success='';try{init(await api.request<DiscoveryStatus>('/host/discovery','PATCH',{enabled,public_url:publicUrl.trim()||null,seeds:lines(seeds),seed_lists:lines(seedLists),blocked:lines(blocked)}));success='Discovery saved. When enabled, listings refresh in the background; refresh host status in a few seconds.';}catch(cause){fail(cause);}finally{busy=false;}}
 async function block(url:string){busy=true;error='';success='';try{const next=await api.request<DiscoveryStatus>('/host/discovery','PATCH',{blocked:[...new Set([...lines(blocked),url])]});status=next;blocked=next.config.blocked.join('\n');success='Host blocked.';}catch(cause){fail(cause);}finally{busy=false;}}
 async function refresh(){busy=true;error='';try{status=await api.request<DiscoveryStatus>('/host/discovery');}catch(cause){fail(cause);}finally{busy=false;}}
 onMount(()=>{void load();});onDestroy(()=>abort.abort());
</script>
<h3>Discovery across hosts</h3><p class="small muted">Host administrator · Hosts exchange public community listings with one another. No central directory is required.</p>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if success}<p class="notice" role="status">{success}</p>{/if}
{#if loading}<p role="status">Loading discovery settings…</p>{:else if status}
<form onsubmit={save}><label class="check-label"><input type="checkbox" bind:checked={enabled}/>Enable the server browser on this host</label><label>Public host address<input type="url" bind:value={publicUrl} required={enabled} placeholder="https://chat.example.org"/></label><p class="small muted">Use the HTTPS address people outside your network can reach, without a path. Only communities whose owners opt in are shared.</p><label>Seed hosts (one address per line)<textarea bind:value={seeds} rows="3" placeholder="https://another.host"></textarea></label><label>Seed list files (one HTTPS file URL per line)<textarea bind:value={seedLists} rows="3"></textarea></label><label>Blocked hosts (one address per line)<textarea bind:value={blocked} rows="3"></textarea></label><button class="primary" disabled={busy}>Save discovery</button></form>
<h3 class="section-heading">Known hosts</h3><p class="small muted">Last background round: {seenAt(status.last_round)}</p><button class="secondary" disabled={busy} onclick={refresh}>Refresh host status</button>
{#each status.hosts as host (host.url)}<div class="settings-row"><div><strong>{host.name||host.url}</strong><p class="small muted">{host.url} · {host.servers} servers · {host.fails} failed checks</p><p class="small muted">Last successful check: {seenAt(host.last_ok)}</p></div><button class="secondary danger" disabled={busy||status.config.blocked.includes(host.url)} onclick={()=>block(host.url)}>{status.config.blocked.includes(host.url)?'Blocked':'Block host'}</button></div>{/each}{#if !status.hosts.length}<p class="notice">No other hosts found yet. Add a seed host or seed list to get started.</p>{/if}
{:else}<button class="secondary" onclick={load}>Retry discovery settings</button>{/if}
